import java.util.EnumMap;

/**
 * TASK: Complete ShippingRateTable. The Zone enum above it is provided --
 * do not edit it.
 *
 * An EnumMap is a map whose keys are enum constants. It is compact and always
 * iterates in declaration order, which makes it the natural lookup table here.
 *
 * - baseRates() returns a FRESH EnumMap with every zone mapped to its base
 *   price in cents: LOCAL 300, REGIONAL 550, NATIONAL 900, INTERNATIONAL 2100.
 *
 * - quoteCents(zone, weightGrams) is the zone's base rate plus 25 cents for
 *   every started block of 100 grams ABOVE 500 grams. 500 grams or less costs
 *   the base rate; 501 grams costs base + 25; 800 grams costs base + 75.
 *
 * - tally(shipments) counts how many shipments went to each zone, as an
 *   EnumMap. Zones that never appear must be absent from the map, not mapped
 *   to 0.
 *
 * Example: quoteCents(Zone.NATIONAL, 800) -> 975
 */
enum Zone { LOCAL, REGIONAL, NATIONAL, INTERNATIONAL }

public class ShippingRateTable {

    public static EnumMap<Zone, Integer> baseRates() {
        EnumMap<Zone, Integer> rates = new EnumMap<>(Zone.class);
        rates.put(Zone.LOCAL, 300);
        rates.put(Zone.REGIONAL, 550);
        rates.put(Zone.NATIONAL, 900);
        rates.put(Zone.INTERNATIONAL, 2100);
        return rates;
    }

    public static int quoteCents(Zone zone, int weightGrams) {
        int base = baseRates().get(zone);
        int over = Math.max(0, weightGrams - 500);
        int blocks = (over + 99) / 100;
        return base + blocks * 25;
    }

    public static EnumMap<Zone, Integer> tally(Zone[] shipments) {
        EnumMap<Zone, Integer> counts = new EnumMap<>(Zone.class);
        for (Zone zone : shipments) {
            counts.merge(zone, 1, Integer::sum);
        }
        return counts;
    }
}
